---@field Rank                          	UnityEngine.RectTransform               
---@field ImgRank1                      	UnityEngine.RectTransform               
---@field ImgRank2                      	UnityEngine.RectTransform               
---@field AniRoot                       	UnityEngine.RectTransform               
---@field PlayerLevel                   	UnityEngine.RectTransform               
---@field CommonPlayerHeadNode          	Engine.Modules.LuaBehaviour             
---@field PlayerName                    	UnityEngine.RectTransform               
local ActivityCatGirlPKRankingCell = Class('ActivityCatGirlPKRankingCell')
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
function ActivityCatGirlPKRankingCell:__init()
    self.data = nil

end

function ActivityCatGirlPKRankingCell:__delete()
    self.data = nil
end

function ActivityCatGirlPKRankingCell:Awake()
end

function ActivityCatGirlPKRankingCell:RefreshShow(data ,isHideSelf)
    self.data = data
    CfUtils.FillText(self.PlayerName,self.data.name)
    CfUtils.FillText(self.PlayerLevel,"Lv."..self.data.level)
   
    CfUtils.FillText(self.DamageNum,checkNumber(self.data.score))
    if isHideSelf ~= true  then
        local isMySelf = GameUtils.IsMySelfPlayerId(self.data.playerId)
        CfUtils.SetActive(self.ImgMyself,isMySelf)
        CfUtils.SetUISwitchText(self.MySelfText,1)    
    end
    
    local isNotRank = checkInt(self.data.percentageRank)  > 0  or (self.data.ranking == 0 and checkInt(self.data.percentageRank) == 0)
    if isNotRank then
        KTool.SetActive(self.ImgRank1.gameObject , false)
        KTool.SetActive(self.ImgRank2.gameObject , false)
        KTool.SetActive(self.Rank.gameObject , false)
        local NotEnterNode = self.Rank.transform.parent:Find("NotEnterNode")
        if isNotNull(NotEnterNode) then
            KTool.SetActive(NotEnterNode , true)
            local TxtRanking2 =  NotEnterNode.transform:Find("TxtRanking2")
            local TxtRanking3 = NotEnterNode.transform:Find("TxtRanking3")
            if checkInt(self.data.percentageRank) == 0 and self.data.ranking == 0 then
                if isNotNull(TxtRanking2) then
                    KTool.SetActive(TxtRanking2 , false)
                    KTool.SetActive(TxtRanking3 , true)
                end
            else 
                if isNotNull(TxtRanking2) then
                    KTool.SetActive(TxtRanking2 , true)
                    KTool.SetActive(TxtRanking3 , false)
                    CfUtils.FillText(TxtRanking2 ,self.data.percentageRank ..   "%")
                end
            end
        end
    else     
        local status = self.data.ranking > 3 and 4 or self.data.ranking
        KTool.SetActive(self.ImgRank1.gameObject , true)
        KTool.SetActive(self.ImgRank2.gameObject , true)
        KTool.SetActive(self.Rank.gameObject , true)
        CfUtils.SetUISwitchImage(self.ImgRank1,status)
        CfUtils.SetUISwitchImage(self.ImgRank2,status)
        CfUtils.FillText(self.Rank,self.data.ranking)
    end
    
    ---@type CommonPlayerHeadNode
    local env = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    if env then
        env:FreshAvatarFrame(self.data.avatar, self.data.avatarFrame)
    end
end

function ActivityCatGirlPKRankingCell:PlayAnimByHide()
    CfUtils.PlayAnimation(self.AniRoot, 'UI_Common_List_Cell_Hide')
end


function ActivityCatGirlPKRankingCell:PlayAnimByIdle()
    CfUtils.PlayAnimation(self.AniRoot, 'UI_Common_List_Cell_Idle')
end


function ActivityCatGirlPKRankingCell:PlayDelayAnimByShow(delayIndex)
    CfUtils.PlayDelayShowAnimation(self.AniRoot, delayIndex, 'UI_Common_List_Cell_Show')
end

function ActivityCatGirlPKRankingCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCatGirlPKRankingCell